import React from 'react'
import PropTypes from 'prop-types'
import { connect } from 'react-redux'
import { Button, Row, Col, Icon } from 'antd'
import LayoutContent from '../../../components/utility/layoutContent'
import LayoutContentWrapper from '../../../components/utility/layoutWrapper'
import TableWrapper from './pagination.style'
import providerAction from '../../redux/provider/actions'
import FailedFetchAlert from '../../../components/failedFetchDataAlert'
import ErrorBoundary from '../../../components/ErrorBoundary'
import AddProviderUserModal from './addProviderUserModal'
import loadingActions from '../../../redux/loading/actions'
import errorActions from '../../../redux/error/actions'
import PermissionChecker from '../../../components/permissionChecker'

const { getProviderUserData, resetReduxState } = providerAction
const { resetLoadingRedux } = loadingActions
const { resetErrorRedux } = errorActions

class ProviderList extends React.Component {
  constructor (props) {
    super(props)
    this.state = {
      providerUserListData: [],
      providerMessage: '',
      showAddProviderUserModal: false
    }
  }

  componentDidMount () {
    this.props.getProviderUserData()
  }

  componentWillUnmount () {
    this.resetReduxState()
  }

  resetReduxState = () => {
    this.props.resetReduxState()
  }

  handleShowAddProviderUserModal = () => {
    this.props.resetReduxState(['userProfile'])
    this.props.resetLoadingRedux(['GET_USER_PROFILE'])
    this.props.resetErrorRedux(['GET_USER_PROFILE'])
    this.setState({
      showAddProviderUserModal: true
    })
  }

  handleCloseAddProviderUserModal = () => {
    this.setState({
      showAddProviderUserModal: false
    })
  }

  render () {
    const {
      providerMessage,
      showAddProviderUserModal
    } = this.state
    const {
      providerUserListData,
      providerUserListDataError,
      providerUserListDataLoading,
      permissions
    } = this.props
    const totalRecords = providerUserListData ? providerUserListData.length : 0
    const columns = [
      {
        key: 'id',
        title: (
          <div
            style={{
              display: 'flex',
              marginLeft: '20px',
              paddingTop: '2px'
            }}
          >
            <span>
              User Id
            </span>
          </div>
        ),
        dataIndex: 'id'
      }, {
        key: 'email',
        title: (
          <div style={{
            display: 'flex',
            marginLeft: '20px',
            paddingTop: '2px'
          }}
          >
            <span>
              Email
            </span>
          </div>
        ),
        dataIndex: 'email'
      }, {
        key: 'name',
        title: (
          <div style={{
            display: 'flex',
            marginLeft: '20px',
            paddingTop: '2px'
          }}
          >
            <span>
              Name
            </span>
          </div>
        ),
        dataIndex: 'name'
      }, {
        key: 'phone',
        title: (
          <div style={{
            display: 'flex',
            marginLeft: '20px',
            paddingTop: '2px'
          }}
          >
            <span>
              Phone
            </span>
          </div>
        ),
        dataIndex: 'phone'
      }, {
        key: 'provider',
        title: (
          <div style={{
            display: 'flex',
            marginLeft: '20px',
            paddingTop: '2px'
          }}
          >
            <span>
              Provider
            </span>
          </div>
        ),
        dataIndex: 'provider'
      }, {
        key: 'agent_provider',
        title: (
          <div style={{
            display: 'flex',
            marginLeft: '20px',
            paddingTop: '2px'
          }}
          >
            <span>
              Agent Provider
            </span>
          </div>
        ),
        dataIndex: 'agent_provider'
      }
    ]
    return (
      <ErrorBoundary>
        <LayoutContentWrapper className='referral-table' style={{ color: '#788195' }}>
          <AddProviderUserModal
            isOpen={showAddProviderUserModal}
            onClosePopupForm={this.handleCloseAddProviderUserModal}
          />
          <Row style={{ width: '100%' }}>
            <Col>
              <FailedFetchAlert
                status='error'
                isNeedDisplay={providerUserListDataError}
                onClose={() => this.resetReduxState()}
                message={providerMessage}
              />
            </Col>
          </Row>
          <LayoutContent>
            <Row style={{ marginBottom: '10px' }}>
              <div>
                <h3 style={{ float: 'left', color: '#788195' }}>Provider User List</h3>
                <div>
                  <p
                    style={{
                      float: 'left',
                      color: '#4482FF',
                      marginLeft: '10px',
                      marginTop: '3px'
                    }}
                  >
                    {totalRecords}
                  </p>
                </div>
              </div>
              <div style={{ float: 'right', display: 'flex' }}>
                <PermissionChecker permissionSetter='ops.add_insurence_user' permissionGetter={permissions}>
                  <Button onClick={this.handleShowAddProviderUserModal}>
                    <Icon type='plus' theme='outlined' /> &nbsp;Add Provider User
                  </Button>
                </PermissionChecker>
              </div>
            </Row>
            <TableWrapper
              columns={columns}
              bordered
              rowKey={record => record.InternalID}
              dataSource={providerUserListData}
              loading={providerUserListDataLoading}
              className='isoSearchableTable'
              scroll={{ x: true }}
            />
          </LayoutContent>
        </LayoutContentWrapper>
      </ErrorBoundary>
    )
  }
}

ProviderList.propTypes = {
  profileData: PropTypes.object
}

ProviderList.defaultProps = {
  profileData: {}
}

export default connect(
  state => ({
    profileData: state.Auth.profile,
    providerUserListData: state.Provider.providerUserList,
    providerUserListDataLoading: state.Loading.GET_PROVIDER_USER_DATA,
    providerUserListDataError: state.Error.GET_PROVIDER_USER_DATA
  }),
  { getProviderUserData, resetReduxState, resetLoadingRedux, resetErrorRedux }
)(ProviderList)
