import React from 'react'
import { connect } from 'react-redux'
import { Form, Input, Button, Modal, Select } from 'antd'
import PropTypes from 'prop-types'
import loadingActions from '../../../redux/loading/actions'
import errorActions from '../../../redux/error/actions'
import providerAction from '../../redux/provider/actions'
import FailedFetchAlert from '../../../components/failedFetchDataAlert'

const FormItem = Form.Item
const Option = Select.Option

const { resetReduxState, getAgentProviderList, postProviderUser, getProviderList } = providerAction
const { resetLoadingRedux } = loadingActions
const { resetErrorRedux } = errorActions

class AddProviderUserModal extends React.Component {
  constructor (props) {
    super(props)
    this.state = {
      providerListData: [],
      agentProviderListData: []
    }
    this.initState = this.state
  }

  componentDidMount () {
    this.resetState()
    this.props.getProviderList()
    this.props.getAgentProviderList()
  }

  componentWillReceiveProps (nextProps) {
    if (nextProps.providerUserMessage &&
      !nextProps.postProviderUserError &&
      !nextProps.postProviderUserLoading) {
      this.handleCancel()
    }
  }

  resetState = () => {
    this.setState(this.initState)
    this.props.resetReduxState(['providerListData', 'providerUserMessage', 'agentProviderListData'])
    this.props.resetLoadingRedux(['GET_PROVIDER_DATA', 'GET_AGENT_PROVIDER_DATA', 'POST_PROVIDER_USER'])
    this.props.resetErrorRedux(['GET_PROVIDER_DATA', 'GET_AGENT_PROVIDER_DATA', 'POST_PROVIDER_USER'])
  }
  async validateForm () {
    return new Promise((resolve) => {
      this.props.form.validateFields((error, values) => {
        resolve(!error)
      })
    })
  }
  onSubmit = async e => {
    e.preventDefault()
    const valid = await this.validateForm()
    if (!valid) {
      return
    }
    const { form } = this.props
    const formValues = form.getFieldsValue()
    let payload = {
      ...formValues
    }
    this.props.postProviderUser(payload)
  }

  handleCancel = () => {
    this.props.form.resetFields()
    this.props.onClosePopupForm()
    this.resetState()
  }

  render () {
    const { getFieldDecorator } = this.props.form
    const {
      providerListData,
      agentProviderListData,
      postProviderUserLoading,
      postProviderUserError,
      providerUserMessage
    } = this.props
    return (
      <Modal
        title='Create Provider User'
        visible={this.props.isOpen}
        onCancel={this.handleCancel}
        footer={null}
        closable
        maskClosable={false} >
        <FailedFetchAlert
          status={'error'}
          isNeedDisplay={postProviderUserError}
          message={providerUserMessage}
        />
        <Form id='event-form' onSubmit={this.onSubmit} style={{ marginTop: '10px' }}>
          <label>
            <strong style={{ padding: '20px 0' }}>Email:</strong>
          </label>
          <FormItem validateStatus>
            {getFieldDecorator('email', {
              rules: [
                { type: 'email', message: 'The input is not a valid E-mail' },
                { required: true, message: 'Email cannot be empty' }
              ]
            })(
              <Input />
            )}
          </FormItem>
          <label>
            <strong style={{ padding: '20px 0' }}>Name:</strong>
          </label>
          <FormItem>
            {
              getFieldDecorator('name', {
                rules: [
                  { required: true, message: 'Name cannot be empty' }
                ]
              })(
                <Input />
              )
            }
          </FormItem>
          <label>
            <strong style={{ padding: '20px 0' }}>Phone:</strong>
          </label>
          <FormItem>
            {
              getFieldDecorator('phone', {
                rules: [
                  { pattern: /^\d{2}-\d{1,}/, message: 'Invalid phone number, format: XX-XXXXXX/[Country code]-[Phone no]' }
                ]
              })(
                <Input />
              )
            }
          </FormItem>
          <label>
            <strong style={{ padding: '20px 0' }}>Provider:</strong>
          </label>
          <FormItem>
            {
              getFieldDecorator('provider', {
                rules: [
                  { required: false, message: 'Must Select a Provider' }
                ]
              })(
                <Select
                  showSearch
                  allowClear
                  placeholder='Select a provider'
                  optionFilterProp='children'
                  filterOption={(input, option) => option.props.children.toLowerCase().indexOf(input.toLowerCase()) >= 0}
                >
                  {
                    providerListData.map((val, index) => {
                      return (
                        <Option
                          key={index}
                          value={val.code}
                        >
                          {val.name}
                        </Option>
                      )
                    })
                  }
                </Select>
              )
            }
          </FormItem>
          <FormItem>
            {
              getFieldDecorator('agent_provider', {
                rules: [
                  { required: false, message: 'Must Select an Agent Provider' }
                ]
              })(
                <Select
                  showSearch
                  allowClear
                  placeholder='Select an agent provider'
                  optionFilterProp='children'
                  filterOption={(input, option) => option.props.children.toLowerCase().indexOf(input.toLowerCase()) >= 0}
                >
                  {
                    agentProviderListData.map((val, index) => {
                      return (
                        <Option
                          key={index}
                          value={val.code}
                        >
                          {val.name}
                        </Option>
                      )
                    })
                  }
                </Select>
              )
            }
          </FormItem>
          <FormItem>
            <Button
              form='event-form'
              className='button'
              key='submit'
              type='primary'
              htmlType='submit'
              style={{ float: 'right', marginTop: '20px' }}
              loading={postProviderUserLoading}
            >
              Create Provider User
            </Button>
          </FormItem>
        </Form>
      </Modal>
    )
  }
}

const WrappedAddProviderUserModal = Form.create()(AddProviderUserModal)

WrappedAddProviderUserModal.propTypes = {
  userProfile: PropTypes.object.isRequired
}

WrappedAddProviderUserModal.defaultProps = {
  userProfile: {}
}

export default connect(
  state => ({
    providerListData: state.Provider.providerList,
    agentProviderListData: state.Provider.agentProviderList,
    providerListDataLoading: state.Loading.GET_PROVIDER_DATA,
    providerListDataError: state.Error.GET_PROVIDER_DATA,
    agentProviderListDataLoading: state.Loading.GET_AGENT_PROVIDER_DATA,
    agentProviderListDataError: state.Error.GET_AGENT_PROVIDER_DATA,
    postProviderUserLoading: state.Loading.POST_PROVIDER_USER,
    postProviderUserError: state.Error.POST_PROVIDER_USER,
    providerUserMessage: state.Provider.providerUserMessage
  }),
  {
    postProviderUser,
    resetReduxState,
    getAgentProviderList,
    getProviderList,
    resetLoadingRedux,
    resetErrorRedux
  }
)(WrappedAddProviderUserModal)
